from pathlib import Path
wiki=Path('/home/zhouhuijuan1987/wiki/llm-wiki-obsidian-blink')
# consider both root folders and wiki/ fallback
base=wiki
if (wiki/'wiki').exists():
    # repo seems to use both; include both trees but avoid double counting identical relative paths by absolute path
    roots=[wiki]
else:
    roots=[wiki]

# Collect md files excluding .git
md_files=[]
for p in wiki.rglob('*.md'):
    if '.git/' in str(p):
        continue
    md_files.append(p)

# bucket counts by top-level dir under repo root
buckets={k:0 for k in ['raw','entities','concepts','comparisons','queries','wiki/entities','wiki/concepts','wiki/comparisons','wiki/queries','logs/webhook-runs']}
for p in md_files:
    rel=p.relative_to(wiki).as_posix()
    for k in list(buckets):
        if rel==k+'.md' or rel.startswith(k+'/'):
            buckets[k]+=1

# Wikilinks and broken links among markdown basenames
wikilink_re=re.compile(r'\[\[([^\]|#]+)')
all_slugs=set([p.stem.lower() for p in md_files])
broken=[]
outbound=0
inbound={}
for p in md_files:
    text=p.read_text(encoding='utf-8',errors='ignore')
    for m in wikilink_re.findall(text):
        target=m.strip().split('/')[-1].lower()
        if not target:
            continue
        outbound+=1
        inbound[target]=inbound.get(target,0)+1
        if target not in all_slugs:
            broken.append((p.relative_to(wiki).as_posix(),target))

# frontmatter presence for knowledge pages (exclude raw and logs)
frontmatter_ok=0
frontmatter_total=0
required=['title:','created:','updated:','type:','tags:','sources:']
missing_samples=[]
for p in md_files:
    rel=p.relative_to(wiki).as_posix()
    if rel.startswith('raw/') or rel.startswith('logs/'):
        continue
    # focus major content dirs
    if not any(rel.startswith(d+'/') for d in ['entities','concepts','comparisons','queries','wiki/entities','wiki/concepts','wiki/comparisons','wiki/queries']):
        continue
    frontmatter_total+=1
    txt=p.read_text(encoding='utf-8',errors='ignore')
    if txt.startswith('---'):
        end=txt.find('\n---',3)
        fm=txt[:end+4] if end!=-1 else txt[:500]
    else:
        fm=''
    miss=[r for r in required if r not in fm]
    if not miss:
        frontmatter_ok+=1
    elif len(missing_samples)<8:
        missing_samples.append({'file':rel,'missing':miss})

# index coverage quick check for root index only
index_path=wiki/'index.md'
index_links=set()
if index_path.exists():
    t=index_path.read_text(encoding='utf-8',errors='ignore')
    for m in wikilink_re.findall(t):
        index_links.add(m.strip().split('/')[-1].lower())

knowledge_pages=[p for p in md_files if any(p.relative_to(wiki).as_posix().startswith(d+'/') for d in ['entities','concepts','comparisons','queries','wiki/entities','wiki/concepts','wiki/comparisons','wiki/queries'])]
not_in_index=[]
for p in knowledge_pages:
    slug=p.stem.lower()
    if slug not in index_links:
        not_in_index.append(p.relative_to(wiki).as_posix())

res={
  'total_md_files':len(md_files),
  'bucket_counts':buckets,
  'wikilinks_total':outbound,
  'broken_wikilinks_count':len(broken),
  'broken_wikilinks_samples':broken[:12],
  'frontmatter_complete_ratio': f"{frontmatter_ok}/{frontmatter_total}",
  'frontmatter_missing_samples':missing_samples,
  'knowledge_pages_not_in_root_index_count':len(not_in_index),
  'knowledge_pages_not_in_root_index_samples':not_in_index[:12],
}
print(json.dumps(res,ensure_ascii=False,indent=2))"}

