{"code":"import re, json
from pathlib import Path
root=Path('/home/zhouhuijuan1987/wiki/llm-wiki-obsidian-blink')
files=[p for p in root.rglob('*.md') if '.git/' not in str(p)]
existing=set(p.relative_to(root).as_posix() for p in files)
name_index={}
for p in files:
    name_index.setdefault(p.stem.lower(),[]).append(p.relative_to(root).as_posix())
wikilink=re.compile(r'\[\[([^\]]+)\]\]')
broken=[]
for p in files:
    text=p.read_text(encoding='utf-8',errors='ignore')
    for raw in wikilink.findall(text):
        target=raw.split('|')[0].split('#')[0].strip()
        if not target: continue
        cands=[]
        t=target.replace('\\','/').lstrip('/')
        if t.endswith('.md'):
            cands.append(t)
        else:
            cands += [t+'.md', t]
        # if path starts wiki/ keep; else could be basename
        ok=False
        for c in cands:
            if c in existing:
                ok=True; break
        if not ok:
            # basename fallback
            stem=Path(t).stem.lower()
            if stem in name_index:
                ok=True
        if not ok:
            broken.append((p.relative_to(root).as_posix(),target))

print(json.dumps({'broken_count':len(broken),'samples':broken[:20]},ensure_ascii=False,indent=2))"}

